<template>
	<!-- :style="{ paddingTop: safeAreaInsets.top + 'px',paddingBottom: safeAreaInsets.bottom + 'px' }" -->
	<view class="container">
		<!-- 读取 -->
		<template>
			<uv-loading-page :loading="loading" loading-text="上传中..." font-size="24rpx"></uv-loading-page>
		</template>
		<uv-navbar leftText="返回" :fixed="false" :title="'编辑' + TDetail.name + '信息'" :safeAreaInsetTop="true">
			<template v-slot:left>
				<view class="uv-nav-slot">
					<!-- <uv-icon name="arrow-left" size="19"></uv-icon> -->
					<uv-button size="mini" text="取消" type="info" :plain="true" @click="back"></uv-button>
					<uv-line direction="column" :hairline="false" length="16" margin="0 8px"></uv-line>
					<uv-button size="mini" text="保存" type="success" :plain="true" @click="addNew"></uv-button>
					<!-- <uv-icon name="home" size="20"></uv-icon> -->
				</view>
			</template>
		</uv-navbar>
		<uni-card :is-shadow="true" shadow="0px 0px 3px 1px rgba(120, 195, 70, 0.8)">
			<!-- <text class="uni-body">这是一个基础卡片示例，内容较少，此示例展示了一个没有任何属性不带阴影的卡片。</text> -->

			<uni-row class="demo-uni-row" :width="nvueWidth">
				<uni-col :span="7">
					<uv-upload :fileList="fileList1" name="1" :maxCount="1" multiple :previewFullImage="true"
						:maxSize="1000000" @afterRead="afterRead" @delete="deletePic"></uv-upload>
				</uni-col>
				<uni-col :span="17">
					<view style="padding-top: 60rpx;">
						<uv-input placeholder="请输入植物昵称"  v-model="TDetail.name" border="bottom" @input="onTNickName"></uv-input>
					</view>
				</uni-col>
			</uni-row>
		</uni-card>

		<uni-card :is-shadow="true" shadow="0px 0px 3px 1px rgba(120, 195, 70, 0.8)">
			<view>
				<uv-text type="success" text="品种"></uv-text>
				<uv-input placeholder="请输入植物品种" @input="onTVariety" v-model="TDetail.variety"></uv-input>
			</view>
			<!-- <view>
				<uv-text type="success" text="性别"></uv-text>
				<uv-radio-group v-model="TDetail.sex" placement="row">
					<uv-radio name="公" activeColor="green" label="公"></uv-radio>
					<uv-radio name="母" activeColor="green" label="母"></uv-radio>
					<uv-radio name="不详" activeColor="green" label="不详"></uv-radio>
				</uv-radio-group>
			</view> -->
			<view>
				<uv-text type="success" text="尺寸"></uv-text>
				<uv-input placeholder="请输入植物尺寸,单位cm" type="digit" v-model="TDetail.length" @input="onTSize"></uv-input>
			</view>
			<!-- <view>
				<uv-text type="success" text="克重"></uv-text>
				<uv-input placeholder="请输入爱龟克重,单位g" type="digit" v-model="TDetail.weight" @input="onTWeight"></uv-input>
			</view> -->
		</uni-card>

		<uni-card :is-shadow="true" shadow="0px 0px 3px 1px rgba(120, 195, 70, 0.8)">
			<view>
				<uv-text type="success" text="标签"></uv-text>
				<uv-list>
					<uv-list-item :title="TTag==''?'添加标签': TTag" v-model="TDetail.feedCycle" clickable link @click="popTag"></uv-list-item>
				</uv-list>
			</view>
			<view>
				<uv-text type="success" text="到家时间"></uv-text>
				<uv-list>
					<uv-list-item :title="getTime(TDetail.birthday)" clickable link @click="dateOpen"></uv-list-item>
				</uv-list>
			</view>
		</uni-card>


		<!-- 标签弹出页面 -->
		<uv-picker ref="picker" :columns="tagList" @confirm="tagConfirm" confirmColor="#5AC725"></uv-picker>

		<!-- 时间选择 -->
		<uv-datetime-picker ref="datetimePicker" v-model="dateValue" mode="date" confirmColor="#5AC725"
			@confirm="dateConfirm"></uv-datetime-picker>


	</view>
</template>

<script>
	export default {
		data() {
			return {
				fileList1: [],
				TDetail:{},
				openId: "",
				safeAreaInsets: "",
				radiovalue: '不详',
				type: 'center',
				showTag: false,
				tagList: [
					[]
				],
				dateValue: Number(new Date()),
				TNickName: '',
				TVariety: '',
				TSize: 0,
				TWeight: 0,
				TTag: '',
				state:0,
				loading:false
			}
		},
		methods: {
			popTag() {
				this.$refs.picker.open();
			},
			tagConfirm(e) {
				this.TDetail.Classification = e.value[0]
			},
			dateOpen() {
				this.$refs.datetimePicker.open();
			},
			dateConfirm(e) {
				this.TDetail.birthday = e.value
			},
			onTNickName(e) {
				this.TDetail.name = e
			},
			onTVariety(e) {
				this.TDetail.variety = e
			},
			onTSize(e) {
				this.TDetail.length = e
			},
			onTWeight(e) {
				this.TDetail.weight = e
			},
			// 删除图片
			deletePic(event) {
				this[`fileList${event.name}`].splice(event.index, 1)
			},
			getTime(timestamp, format = 'YYYY年MM月DD日') {
			  const date = new Date(timestamp);
			  const map = {
			    'YYYY': date.getFullYear(),
			    'MM': (date.getMonth() + 1).toString().padStart(2, '0'),
			    'DD': date.getDate().toString().padStart(2, '0')
			  };
			  return format.replace(/YYYY|MM|DD/g, matched => map[matched]);
			},
			// 新增图片
			async afterRead(event) {
				// 当设置 multiple 为 true 时, file 为数组格式，否则为对象格式
				let lists = [].concat(event.file)
				let fileListLen = this[`fileList${event.name}`].length
				lists.map((item) => {
					this[`fileList${event.name}`].push({
						...item,
						status: 'uploading',
						message: '上传中'
					})
				})
				for (let i = 0; i < lists.length; i++) {
					let item = this[`fileList${event.name}`][fileListLen]
					this[`fileList${event.name}`].splice(fileListLen, 1, Object.assign(item, {
						status: 'success',
						message: '',
						url: lists[0].url
					}))
					fileListLen++
				}
				this.state = 1
			},
			addNew() {
				this.loading = true
				if(this.state == 1){
					let fileID = ''
					if (this.fileList1.length > 0 && this.openId != '') {
						wx.cloud.uploadFile({
								cloudPath: this.openId + "/" + Date.now() + ".jpg", // 上传至云端的路径
								filePath: this.fileList1[0].url, // 小程序临时文件路径，需结合小程序相关 API 获取
							})
							.then((res) => {
								// 返回文件 ID
								console.log(res);
								fileID = res.fileID
								wx.cloud.callFunction({
									name: 'savePrintInfo',
									data: {
										flag: 1,
										_id:this.TDetail._id,
										openId:this.openId,
										weight: this.TDetail.weight,
										length: this.TDetail.length,
										name: this.TDetail.name,
										variety:this.TDetail.variety,
										sex: this.TDetail.sex,
										Classification: this.TDetail.Classification,
										feedCycle: null,
										content: null,
										birthday: this.TDetail.birthday,
										photo: fileID,
					
									},
									complete: res => {
										console.log('callFunction test result: ', res)
										uni.redirectTo({
											url:'/pages/index/index'
										})
									}
								})
							});
					} else {
						uni.showToast({
							title: "请上传图片"
						})
					}
				}else{
					wx.cloud.callFunction({
						name: 'savePrintInfo',
						data: {
							flag: 1,
							_id:this.TDetail._id,
							openId:this.openId,
							weight: this.TDetail.weight,
							length: this.TDetail.length,
							name: this.TDetail.name,
							variety:this.TDetail.variety,
							sex: this.TDetail.sex,
							Classification: this.TDetail.Classification,
							feedCycle: null,
							content: null,
							birthday: this.TDetail.birthday,
							photo: this.TDetail.photo,
										
						},
						complete: res => {
							console.log('callFunction test result: ', res)
							uni.redirectTo({
								url:'/pages/index/index'
							})
						}
					})
				}
				
			},
			getTagList() {
				wx.cloud.callFunction({
					name: 'getClass',
					data: {
						"openId": this.openId,
					},
					complete: res => {
						console.log('callFunction test result: ', res)
						let data = res.result.data
						if (data.length > 0) {
							data.map((item, index) => {
								this.tagList[0].push(item.title)
							})
			
						}
			
					}
				})
			},
			
			back(){
				uni.navigateBack()
			}
		},
		onLoad() {
			this.openId = this.$store.state.openId
			this.TDetail = this.$store.state.TDetail
			let image={"type":"image","url":this.TDetail.photo}
			this.fileList1.push(image)
			// this.getTagList()
			
		},
		mounted() {

		}
	}
</script>

